#include "Epidemic/GameFramework/Abilities/abilities.h"
#include "Epidemic/Foundation/error.h"
using namespace epidemic;using namespace epidemic::gameplay;using namespace epidemic::gameplay::abilities;
namespace {class Resource final:public IAbilityResourceProvider{public:std::int64_t balance=100;[[nodiscard]]bool CanAfford(GameplayObjectRef,AbilityResourceTypeId,std::int64_t a)const override{return balance>=a;}[[nodiscard]]foundation::Result<AbilityResourceReservation> Reserve(GameplayObjectRef,AbilityResourceTypeId t,std::int64_t a,GameplayContext)override{if(balance<a)return foundation::Result<AbilityResourceReservation>::Failure(foundation::Error::Create("no","no"));balance-=a;struct P{std::int64_t a;};return foundation::Result<AbilityResourceReservation>::Success({{GameplayObjectId::FromRaw(1,static_cast<std::uint64_t>(a))},t,RegisteredAbilityPayload::FromTrivial(TypeId::FromString("p"),P{a})});}[[nodiscard]]foundation::Result<void> Commit(const AbilityResourceReservation&,GameplayContext)override{return foundation::Result<void>::Success();}[[nodiscard]]foundation::Result<void> Release(const AbilityResourceReservation&r,GameplayContext)override{struct P{std::int64_t a;};auto p=r.provider_token.AsTrivial<P>(TypeId::FromString("p"));if(!p)return foundation::Result<void>::Failure(foundation::Error::Create("bad","bad"));balance+=p->a;return foundation::Result<void>::Success();}};}
int main(){AbilityService s;Resource res;s.SetResourceProvider(&res);AbilityDefinition d;d.canonical_name="game.fireball";d.targeting=AbilityTargetPolicy::SingleTarget;d.timing.kind=AbilityTimingKind::CastTime;d.timing.cast_duration={5};d.cooldown.group=CooldownGroupId::FromString("game.gcd");d.cooldown.duration={10};AbilityCostDefinition c;c.resource=AbilityResourceTypeId::FromString("game.mana");c.amount_micro=20;c.policy=AbilityCostPolicy::ReserveThenCommit;d.costs.push_back(c);d.outputs.push_back({ActionTypeId::FromString("game.damage"),1'000'000,{}});auto did=s.RegisterDefinition(d);if(!did)return 1;s.Freeze();GameplayObjectRef owner{GameplayDomainId::FromString("test"),GameplayObjectId::FromString("mage")},target{GameplayDomainId::FromString("test"),GameplayObjectId::FromString("enemy")};auto iid=s.Grant(owner,did.Value());if(!iid)return 2;AbilityTargetSet targets;targets.primary=target;auto exec=s.BeginActivation({iid.Value(),targets,{0},{}});if(!exec||res.balance!=80)return 3;if(s.CompleteExecution(exec.Value(),{4}))return 4;auto out=s.CompleteExecution(exec.Value(),{5});if(!out||out.Value().size()!=1||res.balance!=80)return 5;if(s.CanActivate(iid.Value(),targets,{6}).availability!=AbilityAvailability::Unavailable)return 6;if(s.CanActivate(iid.Value(),targets,{15}).availability!=AbilityAvailability::Available)return 7;auto exec2=s.BeginActivation({iid.Value(),targets,{15},{}});if(!exec2||res.balance!=60)return 8;if(!s.Interrupt(exec2.Value(),TypeId::FromString("test.interrupt"),{16})||res.balance!=80)return 9;return 0;}
